// Pseudocode for onMessage
class RuleEngine {
  constructor(windowMs=60000) {
    this.windowMs = windowMs;
    this.state = new Map(); // sensorId -> [{ts,value}, ...], plus sum/count
  }
  onMessage(event){
    const {sensorId, ts, value} = event;
    const bucket = this.state.get(sensorId) || {q:[], sum:0, count:0};
    // prune old
    while (bucket.q.length && bucket.q[0].ts <= ts - this.windowMs) {
      const old = bucket.q.shift(); bucket.sum -= old.value; bucket.count--;
    }
    bucket.q.push({ts,value}); bucket.sum += value; bucket.count++;
    const avg = bucket.count ? bucket.sum / bucket.count : value;
    if (value > 1.2 * avg) { this.emitAlert(sensorId, ts, value, avg); }
    this.state.set(sensorId, bucket);
  }
  rollingAvgFor(sensorId){ const bucket = this.state.get(sensorId); return bucket?.count ? bucket.sum / bucket.count : null; }
  emitAlert(sensorId, ts, value, avg){ // write to threshold_alerts sink
    // sink.write({sensorId, ts, value, avg});
  }
  commitOffsets(){ /* commit after sink write */ }
}
```

## Why This Is Asked

This question evaluates the ability to implement a pragmatic validation gate with dead-letter queue (DLQ) routing in KCNA, along with careful offset management to preserve per-message semantics in a multi-partition, multi-topic environment. It also tests understanding of canary test design for validating end-to-end behavior in production-like scenarios.

## Key Concepts

- Per-message schema validation in KCNA pipelines
- Dead-letter routing and sink isolation for failed records
- Offset management: commit-after-acknowledge pattern for reliability
- Canary test design with mixed valid and invalid records

## Code Example

```javascript
// KCNA validation gate
function validateSchema(msg) {
  const v = msg.value;
  if (!v || typeof v.userId !== 'string' || typeof v.eventType !== 'string' || typeof v.timestamp !== 'number') {
    return { valid: false, error: 'Schema validation failed' };
  }
  return { valid: true };
}

// Process each message
async function processMessage(msg, { producer, commitOffsets }) {
  const validation = validateSchema(msg);

  if (validation.valid) {
    await producer.send({ topic: 'events-validated', messages: [msg] });
    await commitOffsets([{ topic: 'events', partition: msg.partition, offset: msg.offset + 1 }]);
  } else {
    await producer.send({ topic: 'dead_letter', messages: [{ value: { original: msg.value, error: validation.error } }] });
    await commitOffsets([{ topic: 'events', partition: msg.partition, offset: msg.offset + 1 }]);
  }
}

// Canary test scenario
const testRecords = [
  { topic: 'events', partition: 0, value: { userId: 'u123', eventType: 'click', timestamp: 1700000000 } },
  { topic: 'events', partition: 0, value: { userId: 'u456', eventType: 'view' } },
  { topic: 'events', partition: 1, value: { userId: 'u789', eventType: 'purchase', timestamp: 1700000001 } },
];
```

## Why This Is Asked

This question probes ability to design a scalable, auditable governance layer that operates within strict per-tenant boundaries while maintaining low latency in KCNA's streaming pipeline.

## Key Concepts

- Policy representation: graph-based rules, versioned, tenant-scoped
- Real-time evaluation: per-record decisions, caching, cache invalidation
- Privacy vs. usefulness: field-level masking vs. full redaction
- Auditability: tamper-evident logs, provenance tagging, verifiable proofs

## Code Example

```javascript
// Pseudo: evaluatePolicy(tenantId, topic, record) -> { maskFields: [..], sinks: [..], tags: [..] }
function evaluatePolicy(tenantId, topic, record) {
  const policy = policyCache.get(tenantId, topic);
  // apply masking rules
  for (const f of policy.maskFields) {
    if (record.hasOwnProperty(f)) record[f] = mask(record[f]);
  }
  // attach provenance tags
  record._tags = policy.tags;
  return { masked: record, sinks: policy.sinks };
}
```

